 /* R106 (R103-DAT-03): Entwuerfe und Urteile im bestehenden Lernstand, mit Antwortvertrag; nur bei gleichem Vertrag wiederhergestellt */
 const SKEY='r39-algebra',VERTRAG='r39-algebra-1:x6y3:roots0-4';let geladen=false;
 function lager(){try{const S=M.store&&M.store();if(!S)return null;S.teach=S.teach||{};return S.teach;}catch(e){return null;}}
 function laden(){if(geladen)return;const T=lager();if(!T)return;geladen=true;const g=T[SKEY];if(!g||g.contract!==VERTRAG)return;
  ['system','roots'].forEach(k=>{const q=g[k];if(!q||typeof q!=='object')return;Object.keys(draft[k]).forEach(f=>{if(typeof q[f]===typeof draft[k][f])draft[k][f]=q[f];});});}
