 M.algebraSelfTryR39=function(){laden();return '<div class="r39-algebra"><p class="r39-guidance">Trage nur die gesuchten Zahlen ein. Du kannst Hinweise nutzen und deine Antwort danach verbessern. Dieser Lernschritt vergibt keine Pr\u00fcfungsnote.</p><section class="sv37-aufgabe" data-r39-task="system"><span class="sv37-stufe">Gleichungssystem</span><h3>Zwei Bedingungen, eine L\u00f6sung</h3><p>x + y = 9<br>x \u2212 y = 3</p>'+fields('system',[['x','x'],['y','y']])+'<details><summary>Ein kleiner Hinweis</summary><p>Addiere die beiden Gleichungen. +y und \u2212y heben sich auf. Was bleibt auf beiden Seiten stehen?</p></details><button type="button" class="sv37-pruefen" data-r39-check="system">Antwort pr\u00fcfen</button>'+result('system')+'<details class="r39-solution" data-r39-solution="system"'+(draft.system.solutionVisible?'':' hidden')+'><summary>L\u00f6sungsweg mit Probe</summary><p>Durch Addieren folgt 2x = 12, also x = 6. Setze x in x + y = 9 ein: y = 3. Pr\u00fcfe beide Bedingungen: 6 + 3 = 9 und 6 \u2212 3 = 3.</p></details></section><section class="sv37-aufgabe" data-r39-task="roots"><span class="sv37-stufe">Quadratische Gleichung</span><h3>Finde beide Nullstellen</h3><p>2x\u00b2 \u2212 8x = 0</p>'+fields('roots',[['a','Erste Nullstelle'],['b','Zweite Nullstelle']])+'<details><summary>Ein kleiner Hinweis</summary><p>Klammere 2x aus: 2x(x \u2212 4) = 0. Ein Produkt ist null, wenn mindestens einer seiner Faktoren null ist.</p></details><button type="button" class="sv37-pruefen" data-r39-check="roots">Antwort pr\u00fcfen</button>'+result('roots')+'<details class="r39-solution" data-r39-solution="roots"'+(draft.roots.solutionVisible?'':' hidden')+'><summary>L\u00f6sungsweg mit Probe</summary><p>2x = 0 ergibt x = 0. x \u2212 4 = 0 ergibt x = 4. Nicht durch x teilen: Dadurch w\u00fcrde x = 0 verloren gehen. Beide Werte ergeben eingesetzt null.</p></details></section></div>';};
 function evaluate(kind){const d=draft[kind];let correct=false,message;
 if(kind==='system'){
 const x=number(d.x),y=number(d.y);
 if(x===null||y===null)message='F\u00fclle beide Felder mit je einer Zahl aus. Eine Zahlenliste ist keine L\u00f6sung.';
 else if(x===6&&y===3){correct=true;message='Beide Bedingungen stimmen: 6 + 3 = 9 und 6 \u2212 3 = 3. Du hast das Gleichungssystem gel\u00f6st.';}
 else if(x+y===9)message='Die Summe stimmt bereits. Pr\u00fcfe jetzt die zweite Bedingung: x \u2212 y muss 3 ergeben.';
 else if(x-y===3)message='Die Differenz stimmt bereits. Pr\u00fcfe jetzt die erste Bedingung: x + y muss 9 ergeben.';
 else message='Pr\u00fcfe zuerst die Addition beider Gleichungen. Dabei f\u00e4llt y weg. Nutze den Hinweis und versuche es erneut.';
 }else{
 const a=number(d.a),b=number(d.b);
 if(a===null||b===null)message='Trage beide Nullstellen ein. Null ist eine g\u00fcltige Antwort; ein leeres Feld ist keine Null.';
 else if((a===0&&b===4)||(a===4&&b===0)){correct=true;message='Richtig: 0 und 4 sind beide Nullstellen. Ihre Reihenfolge ist egal.';}
 else if(a===b)message='Gesucht sind zwei verschiedene Nullstellen. Pr\u00fcfe beide Faktoren von 2x(x \u2212 4).';
 else message='Klammere 2x aus und setze jeden Faktor einzeln gleich null. Vergiss die L\u00f6sung x = 0 nicht.';
 }
 d.correct=correct;d.message=message;d.shown=true;d.solutionVisible=kind==='system'?number(d.x)!==null&&number(d.y)!==null:number(d.a)!==null&&number(d.b)!==null;sichern();return {correct,message,reveal:d.solutionVisible};
 }
 document.addEventListener('input',e=>{const el=e.target;if(!el.matches?.('[data-r39-field]'))return;const d=draft[el.dataset.r39Kind];if(!d)return;d[el.dataset.r39Field]=el.value;d.shown=false;d.correct=false;sichern();const section=el.closest('[data-r39-task]');section.querySelector('[data-r39-feedback]').hidden=true;section.querySelector('[data-r39-solution]').hidden=true;});
 document.addEventListener('click',e=>{const el=e.target.closest?.('[data-r39-check]');if(!el)return;const kind=el.dataset.r39Check,r=evaluate(kind),section=el.closest('[data-r39-task]'),fb=section.querySelector('[data-r39-feedback]');fb.hidden=false;fb.textContent=r.message;fb.dataset.correct=String(r.correct);section.querySelector('[data-r39-solution]').hidden=!r.reveal;});
 M.SELF_TRY_ALGEBRA_R39={draft,parseNumber:number,evaluate,scope:'Two explicitly authored algebra tasks. No exam score or mastery update.'};
