 if(t.length!==1){ probleme.push(kurz+' ('+t.length+')'); try{ console.error('Kapitel nicht eindeutig:', kurz); }catch(_){} return; }
 var c=t[0]; c.questions=c.questions||[]; var hat={}; c.questions.forEach(function(q){ if(q&&q.id) hat[q.id]=1; });
