if(M.onNavigate) M.onNavigate(function(){ setTimeout(laden,0); });
var go=M.go; if(typeof go==="function"&&!go.__r73){ var neu=function(){ var r=go.apply(this,arguments); setTimeout(laden,0); return r; }; neu.__r73=true; for(var k in go) neu[k]=go[k]; M.go=neu; }
